import React, { useState, useEffect } from 'react';
import Login from './components/auth/Login';
import Header from './components/layout/Header';
import Sidebar from './components/layout/Sidebar';
import StatsCards from './components/dashboard/StatsCards';
import RecentActivity from './components/dashboard/RecentActivity';
import EmployeeForm from './components/employees/EmployeeForm';
import EmployeeList from './components/employees/EmployeeList';
import CredentialPreview from './components/employees/CredentialPreview';
import ReportsSection from './components/reports/ReportsSection';
import QRScanner from './components/qr/QRScanner';
import { apiService } from './services/api';
import { generateRealQRCode, generateRealCredential } from './utils/realQRGenerator';

export default function App() {
  const [currentPage, setCurrentPage] = useState('login');
  const [currentUser, setCurrentUser] = useState(null);
  const [employees, setEmployees] = useState([]);
  const [departments, setDepartments] = useState([]);
  const [positions, setPositions] = useState([]);
  const [loading, setLoading] = useState(true);
  const [newEmployee, setNewEmployee] = useState({ 
    name: '', 
    email: '', 
    position: '', 
    department: '', 
    phone: '', 
    address: '' 
  });
  const [loginForm, setLoginForm] = useState({ username: '', password: '' });
  const [generatedCredential, setGeneratedCredential] = useState(null);
  const [attendanceRecords, setAttendanceRecords] = useState([]);
  const [scanning, setScanning] = useState(false);

  // Cargar datos iniciales
  useEffect(() => {
    if (currentUser) {
      loadInitialData();
    }
  }, [currentUser]);

  const loadInitialData = async () => {
    try {
      setLoading(true);
      console.log('🔄 Cargando datos iniciales...');
      
      const [employeesData, departmentsData, positionsData] = await Promise.all([
        apiService.getEmployees(),
        apiService.getDepartments(),
        apiService.getPositions()
      ]);
      
      console.log('✅ Empleados cargados:', employeesData.length);
      console.log('✅ Departamentos cargados:', departmentsData.length);
      console.log('✅ Puestos cargados:', positionsData.length);
      
      setEmployees(employeesData);
      setDepartments(departmentsData);
      setPositions(positionsData);
      
      // Establecer departamento por defecto
      if (departmentsData.length > 0 && !newEmployee.department) {
        setNewEmployee(prev => ({ ...prev, department: departmentsData[0].name }));
        console.log('🏢 Departamento por defecto:', departmentsData[0].name);
      }
      
      // Establecer puesto por defecto
      if (positionsData.length > 0 && !newEmployee.position) {
        setNewEmployee(prev => ({ ...prev, position: positionsData[0].name }));
        console.log('💼 Puesto por defecto:', positionsData[0].name);
      }
    } catch (error) {
      console.error('❌ Error loading data:', error);
      alert('Error al cargar datos. Verifica que el servidor esté corriendo.');
    } finally {
      setLoading(false);
    }
  };

  const handleLogin = async (e) => {
    e.preventDefault();
    console.log('🔐 Intentando login...', loginForm);
    
    try {
      const user = await apiService.login(loginForm.username, loginForm.password);
      console.log('✅ Login exitoso:', user);
      setCurrentUser(user);
      setCurrentPage('dashboard');
    } catch (error) {
      console.error('❌ Login error:', error);
      alert('Credenciales inválidas o error de conexión. Usando modo demo.');
      
      // Fallback para desarrollo
      const mockUsers = [
        { username: 'admin', password: 'admin123', role: 'administrador', fullName: 'Administrador del Sistema' },
        { username: 'maria.lopez', password: 'admin123', role: 'recursos_humanos', fullName: 'María López' }
      ];
      
      const user = mockUsers.find(u => u.username === loginForm.username && loginForm.password === 'admin123');
      if (user) {
        console.log('✅ Login fallback exitoso:', user);
        setCurrentUser(user);
        setCurrentPage('dashboard');
      } else {
        console.log('❌ Login fallback fallido');
        alert('Credenciales inválidas. Use: admin/admin123');
      }
    }
  };

  const handleLogout = () => {
    console.log('🚪 Cerrando sesión...');
    apiService.logout();
    setCurrentUser(null);
    setCurrentPage('login');
    setLoginForm({ username: '', password: '' });
    setGeneratedCredential(null);
    setAttendanceRecords([]);
  };

  const handleAddEmployee = async (e) => {
    e.preventDefault();
    console.log('🔧 Iniciando creación de empleado...');
    console.log('📝 Datos del formulario:', newEmployee);
    
    if (newEmployee.name && newEmployee.email && newEmployee.position && newEmployee.department) {
      try {
        console.log('📤 Enviando datos al servidor...');
        const createdEmployee = await apiService.createEmployee(newEmployee);
        console.log('✅ Empleado creado en BD:', createdEmployee);
        
        // Actualizar lista de empleados
        console.log('🔄 Actualizando lista de empleados...');
        const updatedEmployees = await apiService.getEmployees();
        setEmployees(updatedEmployees);
        console.log('✅ Lista actualizada:', updatedEmployees.length, 'empleados');
        
        // Generar credencial y QR REAL
        console.log('🎨 Generando credencial y QR REAL...');
        console.log('📱 QR Code del empleado:', createdEmployee.qrCode);
        
        const credentialImage = await generateRealCredential(createdEmployee);
        const qrImage = await generateRealQRCode({
          employeeId: createdEmployee.qrCode,
          name: createdEmployee.name,
          department: createdEmployee.department,
          type: 'attendance'
        });
        
        console.log('🖼️ Credencial generada:', credentialImage ? 'SÍ' : 'NO');
        console.log('📱 QR generado:', qrImage ? 'SÍ' : 'NO');
        console.log('📏 Longitud QR:', qrImage?.length);
        console.log('📏 Longitud Credencial:', credentialImage?.length);
        
        if (!credentialImage || !qrImage) {
          console.error('❌ Error: No se generaron las imágenes');
          alert('Error generando credenciales. Verifica la consola.');
          return;
        }
        
        setGeneratedCredential({
          employee: createdEmployee,
          credentialImage: credentialImage,
          qrImage: qrImage
        });
        
        console.log('✅ Credenciales guardadas en estado');
        
        // Reset form
        setNewEmployee({ 
          name: '', 
          email: '', 
          position: positions[0]?.name || '', 
          department: departments[0]?.name || '', 
          phone: '', 
          address: '' 
        });
        
        console.log('🎉 Proceso completado exitosamente');
        
      } catch (error) {
        console.error('❌ Error creando empleado:', error);
        alert('Error al crear empleado. Verifica los datos e intenta nuevamente.');
      }
    } else {
      console.log('⚠️ Campos incompletos:', {
        name: !!newEmployee.name,
        email: !!newEmployee.email,
        position: !!newEmployee.position,
        department: !!newEmployee.department
      });
      alert('Por favor, complete todos los campos obligatorios.');
    }
  };

  // Manejar escaneo exitoso de QR
  const handleScanSuccess = async (employeeData) => {
    console.log('✅ QR escaneado - Empleado detectado:', employeeData);
    
    try {
      // Buscar empleado en la lista local para verificar
      const employee = employees.find(emp => 
        emp.qrCode === employeeData.employeeId || 
        emp.codigo_empleado === employeeData.employeeId
      );
      
      if (!employee) {
        alert('❌ Empleado no encontrado en el sistema');
        return;
      }
      
      // Registrar asistencia en el servidor
      console.log('📝 Registrando asistencia en servidor...');
      await apiService.registerAttendance({
        employeeId: employee.id || employeeData.employeeId,
        tipoRegistro: 'entrada',
        latitud: null, // En producción, obtener geolocalización
        longitud: null,
        direccionIp: 'localhost', // En producción, obtener IP real
        dispositivo: 'Sistema QR Web'
      });
      
      // Agregar a registros locales
      const newRecord = {
        id: Date.now(),
        employeeId: employeeData.employeeId,
        name: employeeData.name,
        department: employeeData.department,
        timestamp: new Date().toISOString(),
        type: 'entrada',
        status: 'success'
      };
      
      setAttendanceRecords(prev => [newRecord, ...prev]);
      
      console.log('✅ Asistencia registrada exitosamente');
      alert(`✅ Asistencia registrada para ${employeeData.name}\nHora: ${new Date().toLocaleTimeString()}`);
      
      // Actualizar lista de empleados para reflejar cambios
      const updatedEmployees = await apiService.getEmployees();
      setEmployees(updatedEmployees);
      
    } catch (error) {
      console.error('❌ Error registrando asistencia:', error);
      
      // Agregar registro fallido
      const failedRecord = {
        id: Date.now(),
        employeeId: employeeData.employeeId,
        name: employeeData.name,
        department: employeeData.department,
        timestamp: new Date().toISOString(),
        type: 'entrada',
        status: 'error',
        error: error.message
      };
      
      setAttendanceRecords(prev => [failedRecord, ...prev]);
      
      alert(`❌ Error registrando asistencia: ${error.message}`);
    }
  };

  // Manejar error en escaneo
  const handleScanError = (error) => {
    console.error('❌ Error en escaneo:', error);
    alert(`Error en escaneo: ${error}`);
  };

  const downloadImage = (dataUrl, filename) => {
    console.log('💾 Descargando imagen:', filename);
    console.log('📏 Longitud data URL:', dataUrl?.length);
    
    if (!dataUrl) {
      console.error('❌ No hay data URL para descargar');
      alert('Error: No se puede descargar la imagen');
      return;
    }
    
    try {
      const link = document.createElement('a');
      link.href = dataUrl;
      link.download = filename;
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
      console.log('✅ Descarga iniciada');
    } catch (error) {
      console.error('❌ Error en descarga:', error);
      alert('Error al descargar la imagen');
    }
  };

  const testQRGeneration = async () => {
    console.log('🧪 Probando generación de QR REAL...');
    
    const testEmployee = {
      name: 'Empleado de Prueba',
      position: 'Desarrollador',
      department: 'Tecnología',
      qrCode: 'TEST123'
    };
    
    try {
      const qr = await generateRealQRCode(testEmployee);
      const credential = await generateRealCredential(testEmployee);
      
      console.log('QR generado:', qr ? 'SÍ' : 'NO');
      console.log('Credencial generada:', credential ? 'SÍ' : 'NO');
      
      // Mostrar en el DOM temporalmente
      const testDiv = document.getElementById('debug-test');
      if (testDiv) {
        testDiv.innerHTML = '';
        
        if (qr) {
          const qrImg = document.createElement('img');
          qrImg.src = qr;
          qrImg.style.width = '200px';
          qrImg.style.border = '2px solid green';
          qrImg.style.margin = '10px';
          qrImg.alt = 'QR de prueba';
          testDiv.appendChild(qrImg);
          
          // Agregar instrucciones
          const instructions = document.createElement('p');
          instructions.textContent = 'Este QR ES ESCANEABLE con cualquier app de QR';
          instructions.style.color = 'green';
          instructions.style.fontWeight = 'bold';
          instructions.style.margin = '10px';
          testDiv.appendChild(instructions);
        }
        
        if (credential) {
          const credImg = document.createElement('img');
          credImg.src = credential;
          credImg.style.width = '400px';
          credImg.style.border = '2px solid blue';
          credImg.style.margin = '10px';
          credImg.alt = 'Credencial de prueba';
          testDiv.appendChild(credImg);
        }
      }
    } catch (error) {
      console.error('❌ Error en prueba QR:', error);
      alert('Error en prueba QR: ' + error.message);
    }
  };

  const renderMainContent = () => {
    if (loading) {
      return (
        <div className="flex justify-center items-center h-64">
          <div className="text-lg text-gray-600">Cargando datos...</div>
        </div>
      );
    }

    switch (currentPage) {
      case 'dashboard':
        return (
          <div className="space-y-8">
            <StatsCards employees={employees} attendanceRecords={attendanceRecords} />
            <RecentActivity employees={employees} />
            
            {/* Registros recientes de asistencia */}
            {attendanceRecords.length > 0 && (
              <div className="bg-white rounded-2xl shadow-lg p-6">
                <h2 className="text-2xl font-bold text-gray-900 mb-4">Registros de Asistencia Recientes</h2>
                <div className="space-y-3">
                  {attendanceRecords.slice(0, 5).map((record) => (
                    <div key={record.id} className={`flex justify-between items-center p-4 rounded-lg ${
                      record.status === 'success' ? 'bg-green-50 border border-green-200' : 'bg-red-50 border border-red-200'
                    }`}>
                      <div>
                        <p className="font-medium text-gray-900">{record.name}</p>
                        <p className="text-sm text-gray-600">{record.employeeId} • {record.department}</p>
                      </div>
                      <div className="text-right">
                        <p className={`text-sm font-medium ${
                          record.status === 'success' ? 'text-green-600' : 'text-red-600'
                        }`}>
                          {record.status === 'success' ? '✅ Entrada registrada' : '❌ Error'}
                        </p>
                        <p className="text-xs text-gray-500">
                          {new Date(record.timestamp).toLocaleTimeString()}
                        </p>
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            )}
          </div>
        );

      case 'scanner':
        return (
          <div className="space-y-6">
            <div className="bg-white rounded-2xl shadow-lg p-6">
              <h2 className="text-2xl font-bold text-gray-900 mb-4">
                Registro de Asistencia por QR
              </h2>
              <QRScanner 
                onScanSuccess={handleScanSuccess}
                onScanError={handleScanError}
              />
            </div>
            
            {/* Historial de registros del día */}
            <div className="bg-white rounded-2xl shadow-lg p-6">
              <div className="flex justify-between items-center mb-4">
                <h3 className="text-xl font-bold text-gray-900">
                  Registros de Hoy
                </h3>
                <span className="bg-blue-100 text-blue-800 text-sm font-medium px-3 py-1 rounded-full">
                  {attendanceRecords.length} registros
                </span>
              </div>
              
              {attendanceRecords.length > 0 ? (
                <div className="space-y-3 max-h-96 overflow-y-auto">
                  {attendanceRecords.map((record) => (
                    <div key={record.id} className={`flex justify-between items-center p-4 rounded-lg border ${
                      record.status === 'success' ? 'border-green-200 bg-green-50' : 'border-red-200 bg-red-50'
                    }`}>
                      <div className="flex-1">
                        <div className="flex items-center space-x-3">
                          <div className={`w-3 h-3 rounded-full ${
                            record.status === 'success' ? 'bg-green-500' : 'bg-red-500'
                          }`}></div>
                          <div>
                            <p className="font-medium text-gray-900">{record.name}</p>
                            <p className="text-sm text-gray-600">
                              {record.employeeId} • {record.department}
                            </p>
                          </div>
                        </div>
                      </div>
                      <div className="text-right">
                        <p className={`text-sm font-medium ${
                          record.status === 'success' ? 'text-green-600' : 'text-red-600'
                        }`}>
                          {record.status === 'success' ? 'ENTRADA' : 'ERROR'}
                        </p>
                        <p className="text-xs text-gray-500">
                          {new Date(record.timestamp).toLocaleTimeString()}
                        </p>
                        {record.error && (
                          <p className="text-xs text-red-500 mt-1">{record.error}</p>
                        )}
                      </div>
                    </div>
                  ))}
                </div>
              ) : (
                <div className="text-center py-8 text-gray-500">
                  <p>No hay registros de asistencia hoy</p>
                  <p className="text-sm mt-1">Use el escáner QR para registrar entradas</p>
                </div>
              )}
            </div>
          </div>
        );

      case 'reports':
        return <ReportsSection employees={employees} attendanceRecords={attendanceRecords} />;

      case 'employees':
        return (
          <div className="space-y-8">
            {/* Debug Section - Temporal */}
            <div className="bg-yellow-50 border border-yellow-200 rounded-lg p-4">
              <h3 className="text-lg font-semibold text-yellow-800 mb-2">Prueba de QR Real</h3>
              <button 
                onClick={testQRGeneration}
                className="bg-yellow-500 text-white px-4 py-2 rounded-lg hover:bg-yellow-600 transition-colors font-medium"
              >
                Probar Generación de QR Real
              </button>
              <p className="text-sm text-yellow-700 mt-2">
                Este botón genera un QR REAL que puedes escanear con cualquier app de QR
              </p>
              <div id="debug-test" className="mt-3"></div>
            </div>
            
            <div className="bg-white rounded-2xl shadow-lg p-8">
              <div className="flex justify-between items-center mb-6">
                <h2 className="text-2xl font-bold text-gray-900">Gestión de Empleados</h2>
                <div className="text-sm text-gray-600">
                  Total: {employees.length} empleados registrados
                </div>
              </div>
              
              <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
                <EmployeeForm 
                  newEmployee={newEmployee}
                  setNewEmployee={setNewEmployee}
                  handleAddEmployee={handleAddEmployee}
                  departments={departments}
                  positions={positions}
                />
                
                {generatedCredential ? (
                  <CredentialPreview 
                    generatedCredential={generatedCredential}
                    downloadImage={downloadImage}
                  />
                ) : (
                  <EmployeeList employees={employees} />
                )}
              </div>
            </div>
          </div>
        );

      default:
        return null;
    }
  };

  if (currentPage === 'login') {
    return (
      <Login 
        loginForm={loginForm}
        setLoginForm={setLoginForm}
        handleLogin={handleLogin}
      />
    );
  }

  return (
    <div className="min-h-screen bg-gray-50">
      <Header currentUser={currentUser} handleLogout={handleLogout} />
      
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        <div className="flex flex-col lg:flex-row gap-8">
          <div className="lg:w-64 flex-shrink-0">
            <Sidebar 
              currentPage={currentPage}
              setCurrentPage={setCurrentPage}
              employees={employees}
              setGeneratedCredential={setGeneratedCredential}
            />
          </div>

          <div className="flex-1">
            {renderMainContent()}
          </div>
        </div>
      </div>
    </div>
  );
}
